<script setup lang="ts">import {ref,computed} from 'vue';import PageHeading from '../components/common/PageHeading.vue';import RunList from '../components/RunList.vue';import Notice from '../components/common/Notice.vue';import {useTask} from '../hooks/useTask';import {researchApi} from '../api/research';const p=defineProps<{studies:any[];specimens:any[];runs:any[];user:any;reloadResearch:()=>Promise<void>}>(),emit=defineEmits(['open']);const id=ref(0),name=ref('固定面板一致性 '+new Date().toLocaleTimeString()),B=ref(400),seed=ref(231),task=useTask(),study=computed(()=>p.studies.find(s=>s.id===(id.value||p.studies[0]?.id))),N=computed(()=>p.specimens.filter(s=>s.study_id===study.value?.id).length);async function run(){await task.act(async()=>{const r=await researchApi.createRun({study_id:study.value.id,name:name.value,bootstrap_repeats:B.value,seed:seed.value,panel_scope:'fixed_three_raters'});await p.reloadResearch();emit('open',r)},'κ与整样本bootstrap已排队')}</script><template><PageHeading index="03" title="固定面板，整试样重采样。" description="参数在运行前确定；不按单票重采样，不把新标记者抽样误差混入。"/><div class="config-layout"><form class="input-sheet" @submit.prevent="run"><label>拟合研究<select :value="study?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>运行名称<input v-model="name" required/></label><div class="field-pair"><label>bootstrap重复 B<input v-model.number="B" type="number" min="400" max="1000" required/></label><label>随机种子 seed<input v-model.number="seed" type="number" min="0" max="1000000000" required/></label></div><p>本研究{{N}}个独立试样，{{study?.raters.join(' / ')}}固定面板。经验区间95%，线性percentile；有效比例≥90%才报告。</p><button v-if="user.role!=='viewer'" class="primary" :disabled="task.state.busy||!study">送入κ与bootstrap队列 →</button><p v-else>观察员只读已有研究。</p><Notice v-bind="task.state"/></form><aside class="method-note"><small>AGREEMENT / NOT ACCURACY</small><h2>κ = (P̄ − Pe)<br/>÷ (1 − Pe)</h2><p>Pᵢ按同一试样的成对一致计算，Pe来自全部票的类别基率。</p><p>Pe=1时κ未定义。全同类不能标κ1；全一致且多类别时可以κ1。</p><p>Bootstrap每次抽完整计数行，退化重复保留原因及数量，未补抽。条件是试样iid、面板固定。</p></aside></div><section class="section"><h2>核算队列与归档</h2><RunList :runs="runs" @open="emit('open',$event)"/></section></template>
